(() => {
'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fixture={fear:91,drawdown:-20,stabilize:1.2658,volume:1.4,market:-4,market50:-2,sector:-7,breadth:28,stock:-8,aligned:true,panicAligned:true,environmentAligned:true,broken:'unknown'};
let mode='demo',values={...fixture},sources=[],research=null,bars=[],busy=false,sequence=0,controller,quote=null,chartMessage='',change='',liveError='',researchReady=true;
const day=()=>new Date().toISOString().slice(0,10),in30=()=>new Date(Date.now()+30*86400000).toISOString().slice(0,10);
function demoBars(){const a=[];let date=new Date('2026-05-01T00:00:00Z');for(let i=0;i<80;){if(![0,6].includes(date.getUTCDay())){let c=i<25?87+i*.52:i<76?100-(i-25)*.49+Math.sin(i)*.5:[75.8,76.4,77.8,80][i-76];a.push({date:date.toISOString().slice(0,10),c:Math.min(100,c)});i++;}date.setUTCDate(date.getUTCDate()+1);}return a;}
function fill(r){for(const [id,key] of [['fair','fairValue'],['revision','revision'],['fiscal','fiscalYear'],['broken','broken'],['rationale','rationale'],['source','sourceUrl'],['asof','asOf'],['expires','expiresOn']])$(id).value=r?.[key]??(id==='broken'?'unknown':'');}
function status(text,error=false){$('form-status').textContent=text;$('form-status').classList.toggle('error',error);}
function applyResearch(r){const active=r&&r.expiresOn>=day();values={...fixture,broken:active?r.broken:'unknown',upside:active&&r.fairValue!=null?(r.fairValue/80-1)*100:null,revision:active?r.revision:null};}
function chart(){const svg=$('price-chart');if(!bars.length){svg.innerHTML='<text x="360" y="110" text-anchor="middle">'+esc(busy?'正在读取价格…':'暂无可用日线，请稍后刷新')+'</text>';return;}const ma=bars.map((b,i)=>i>=49?bars.slice(i-49,i+1).reduce((s,x)=>s+x.c,0)/50:null),start=Math.max(0,bars.length-100),a=bars.slice(start),m=ma.slice(start),all=a.map(r=>r.c).concat(m.filter(Number.isFinite)),low=Math.min(...all)*.97,high=Math.max(...all)*1.03,x=i=>48+i*620/Math.max(1,a.length-1),y=v=>192-(v-low)/(high-low||1)*164;let html='<title>NBIS '+(mode==='demo'?'假设价格走势':'历史收盘价')+'</title>';for(let i=0;i<4;i++){const v=low+(high-low)*i/3;html+=`<line x1="48" y1="${y(v)}" x2="680" y2="${y(v)}" stroke="#e7edeb"/><text x="3" y="${y(v)+4}">${v.toFixed(0)}</text>`;}const path=arr=>arr.map((v,i)=>Number.isFinite(v)?`${i===0||!Number.isFinite(arr[i-1])?'M':'L'}${x(i).toFixed(1)},${y(v).toFixed(1)}`:'').join(' ');html+=`<path d="${path(a.map(r=>r.c))}" fill="none" stroke="#247367" stroke-width="2.5"/><path d="${path(m)}" fill="none" stroke="#bd883b" stroke-width="1.8"/><circle cx="${x(a.length-1)}" cy="${y(a.at(-1).c)}" r="4" fill="#247367"/><text x="48" y="222">${esc(a[0].date)}</text><text x="590" y="222">${esc(a.at(-1).date)}</text>`;svg.innerHTML=html;}
function render(){const demo=mode==='demo',c=EntryCompleteness(values,sources,'auto'),r=EntryEngine.evaluate(values),complete=c.currentPhase==='complete',blocked=values.broken==='yes';
$('demo-mode').setAttribute('aria-pressed',String(demo));$('live-mode').setAttribute('aria-pressed',String(!demo));$('mode-note').classList.toggle('live',!demo);$('mode-note').textContent=demo?'演示模式 · 所有价格、指标和研究均为假设，仅用于体验流程，不代表 NBIS 当前行情。':busy?'真实数据 · 正在获取已完成日线与已保存研究…':'真实数据 · 使用已获取数据；缺失、过期和人工研究会分别标明。';
$('tour').hidden=!demo;$('risk-demo').hidden=!demo;$('fill-example').hidden=!demo;$('data-badge').textContent=demo?'假设场景':'真实观察';$('research-badge').textContent=demo?'仅本次演示':'保存到我的研究';$('research-help').textContent=demo?'先填入示例，再保存。演示研究只在本次页面中生效，刷新后重置。':'填写有来源的研究，保存后用于 NBIS 的真实判断。留空项保持未知。';
let title,copy,next;if(busy){title='正在整理证据';copy='先读取价格和研究，再评估两条路径。';next='等待数据返回。';}else if(blocked){title='基本面拦截';copy='经营假设已失效。即使价格条件成立，也会撤销候选。';next='重新核实经营假设，更新研究依据。';}else if(complete){title='低吸路径候选';if(!r.panicComplete)title='趋势路径候选';copy='至少一条完整路径满足规则，进入来源与近期事件复核。';next=demo?'继续模拟经营假设失效，观察判断如何撤销。':'复核来源日期、估值假设与近期经营事件。';}else{title=demo?(research?'等待 · 研究条件未通过':'技术条件已满足 · 研究待补齐'):liveError?'数据暂不可用':'等待 · 证据尚未齐备';copy=demo?(research?'价格条件已满足，但填写的研究尚未满足完整确认要求。请查看缺失、未满足或过期的证据。':'回撤、企稳和量能已通过。还需要估值空间、收入预期与经营核查，才能进入完整候选。'):liveError||'下面分开列出缺少的数据与尚未达到的条件，不把未知当作通过。';const p=c.paths.panic;next=p.missing.length?'补齐'+p.missing.slice(0,2).join('、')+'。':p.unmet.length?'等待'+p.unmet[0]+'。':'核实基本面状态。';}
$('verdict-title').textContent=title;$('verdict-copy').textContent=copy;$('next-copy').textContent=next;$('state-dot').className='state-dot '+(blocked?'blocked':complete?'complete':'');$('open-research').textContent=complete&&demo?'体验风险拦截 ↓':'补充研究依据 →';$('open-research').disabled=busy;
$('paths').innerHTML=Object.values(c.paths).map(p=>`<article class="path"><div class="path-heading"><h3>${p.name==='panic'?'01 / 恐慌低吸':'02 / 趋势买入'}</h3><span class="path-status">${blocked?'被拦截':p.complete?'完整候选':(p.checks.filter(x=>x.status==='met').length+(values.broken==='no'?1:0))+' / '+(p.checks.length+1)+' 项'}</span></div>${p.checks.map(k=>`<div class="check"><span class="check-icon ${k.status}">${k.status==='met'?'✓':k.status==='missing'?'?':'−'}</span><div>${esc(k.label)}<small>${k.status==='missing'?'缺少证据':Number.isFinite(k.value)?'当前 '+k.value.toFixed(2):''} · 需 ${esc(({volume:p.name==='panic'?'≥ 1 倍':'≥ 1.2 倍',upside:p.name==='panic'?'≥ 15%':'≥ 5%',revision:p.name==='panic'?'≥ −5%':'≥ 0%'})[k.key]||k.target)}</small></div></div>`).join('')}<div class="check"><span class="check-icon ${values.broken==='no'?'met':'missing'}">${values.broken==='no'?'✓':blocked?'!':'?'}</span><div>基本面核查<small>${blocked?'已失效 · 否决路径':values.broken==='no'?'人工核实未失效':'尚未核实'}</small></div></div></article>`).join('');
$('change-note').hidden=!change;$('change-note').textContent=change;$('tour-caption').textContent=blocked?'③ 已体验风险拦截 · 一条新证据也能撤销候选':complete?'② 已补齐研究，进入候选 · 下一步体验风险拦截':'① 价格条件已满足 · 点击「填入演示研究」继续';$('apply-risk').disabled=!complete;$('restore-demo').hidden=!blocked;
$('chart-label').textContent=demo?'假设日线 / 非历史行情':'最近 100 根日线';$('last-price').textContent=quote!=null?'$'+quote.toFixed(2):'—';$('price-date').textContent=bars.length?(demo?'演示收盘':'数据截至')+' '+bars.at(-1).date:'';$('chart-disclaimer').textContent=demo?'假设走势，仅演示':'原始收盘 / 未复权';$('chart-status').textContent=chartMessage;
$('source-list').innerHTML=demo?'<p>价格曲线和全部指标是为演示设定的假设。演示研究不写入数据库，也不替代真实模式中的已有记录。</p>':sources.map(s=>`<div class="source-row"><b>${esc(s.label)}</b> · ${esc(s.date||'日期未知')}<p>${esc(s.message)}</p>${/^https:\/\//.test(s.url||'')?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a>`:''}</div>`).join('')||'<p>尚未取得来源信息。</p>';
$('save').disabled=busy||!researchReady;$('save').textContent=busy?'正在处理…':demo?'应用演示研究并重新判断':'保存并重新判断';chart();}
function setDemo(){sequence++;controller?.abort();mode='demo';busy=false;researchReady=true;values={...fixture};sources=[];research=null;bars=demoBars();quote=80;change='';liveError='';chartMessage='演示终点 $80；完整低吸路径要求估值空间 ≥15%、收入修正 ≥−5%、基本面核查。';fill(null);status('');render();}
async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options});if(!response.ok)throw Error('暂时无法读取或保存，请稍后重试。');return response.json();}
async function loadLive(){sequence++;const seq=sequence;controller?.abort();controller=new AbortController();const signal=AbortSignal.any([controller.signal,AbortSignal.timeout(30000)]);mode='live';busy=true;researchReady=false;values={broken:'unknown'};research=null;sources=[];quote=null;bars=[];change='';chartMessage='';liveError='';fill(null);status('');render();const results=await Promise.allSettled([api('/api/market?symbol=NBIS',{signal}),api('/api/history?symbol=NBIS',{signal}),api('/api/research?symbol=NBIS',{signal})]);if(seq!==sequence)return;const [market,history,record]=results;if(market.status==='fulfilled'){values=market.value.values||{broken:'unknown'};sources=market.value.sources||[];}else liveError='市场数据读取失败；请切回演示体验完整流程，或点击真实数据重试。';if(history.status==='fulfilled'){const h=history.value;bars=(h.bars||[]).filter(b=>Number.isFinite(b.c));quote=bars.at(-1)?.c??null;chartMessage=`${h.source||'来源未知'} · ${h.status==='ok'?'已获取':h.status==='cached'?'数据库缓存':h.status==='stale'?'已过期':h.status==='review'?'价格跳变待核实':'数据不足'} · ${bars.length} 根日线。图表独立获取，判断以路径证据日期为准。`;}else chartMessage='日线读取失败，可点击真实数据重试。';if(record.status==='fulfilled'){researchReady=record.value.status!=='disabled'&&record.value.status!=='error';research=record.value.record;fill(research);status(record.value.status==='expired'?'研究已过期，请更新依据。':research?'已读取保存的研究。':'尚无研究，填写后保存。');}else status('研究读取失败，暂不允许覆盖已有记录。点击真实数据重试。',true);if(record.status==='fulfilled'&&!researchReady)status('研究存储暂不可用，暂不能保存。',true);busy=false;render();}
$('demo-mode').onclick=setDemo;$('live-mode').onclick=loadLive;$('restart').onclick=setDemo;
$('open-research').onclick=()=>{const complete=EntryCompleteness(values,sources,'auto').currentPhase==='complete';const target=mode==='demo'&&complete?$('apply-risk'):$('fair');target.scrollIntoView({behavior:'smooth',block:'center'});target.focus({preventScroll:true});};
$('fill-example').onclick=()=>{fill({fairValue:104,revision:2,fiscalYear:2026,broken:'no',rationale:'【假设演示】考虑稀释后的合理价值为 $104，同财年收入共识较30日前上修2%，假设本次经营核查未发现失效证据。不是对 NBIS 的真实研究。',sourceUrl:'https://example.com/demo-research',asOf:day(),expiresOn:in30()});status('示例已填入，点击下方按钮应用。此链接为占位示例。');$('save').scrollIntoView({behavior:'smooth',block:'center'});};
$('research-form').onsubmit=async e=>{e.preventDefault();if(busy||!researchReady)return;const f=new FormData(e.currentTarget),record={fairValue:f.get('fairValue')===''?null:Number(f.get('fairValue')),revision:f.get('revision')===''?null:Number(f.get('revision')),fiscalYear:f.get('fiscalYear')||null,broken:f.get('broken'),rationale:f.get('rationale').trim(),sourceUrl:f.get('sourceUrl'),asOf:f.get('asOf'),expiresOn:f.get('expiresOn')};if(record.revision!=null&&!/^\d{4}$/.test(record.fiscalYear||'')){status('填写收入修正时，请填写四位财年。',true);return;}if(!record.rationale||!/^https:\/\//.test(record.sourceUrl)||record.asOf>day()||record.expiresOn<record.asOf||Date.parse(record.expiresOn)-Date.parse(record.asOf)>90*86400000){status('请填写依据与 HTTPS 链接；依据日期不能在未来，有效期需在依据日期后 90 日内。',true);return;}const before=$('verdict-title').textContent;if(mode==='demo'){research=record;applyResearch(record);change='';render();change=`本次变化：${before} → ${$('verdict-title').textContent}。应用了你填写的演示研究。`;status(record.expiresOn<day()?'研究已过期，没有用于判断。':'演示研究已应用，仅在本页面中生效。');render();$('verdict-title').scrollIntoView({behavior:'smooth',block:'center'});return;}
const seq=sequence;busy=true;render();status('正在保存研究…');try{const saved=await api('/api/research?symbol=NBIS',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(record),signal:AbortSignal.timeout(15000)});if(seq!==sequence)return;research=saved.record;status('已保存，正在重新读取判断…');try{const m=await api('/api/market?symbol=NBIS',{signal:AbortSignal.timeout(30000)});if(seq!==sequence)return;values=m.values;sources=m.sources;busy=false;render();change=`研究已保存：${before} → ${$('verdict-title').textContent}。`;status('已保存并重新判断。');}catch{if(seq!==sequence)return;values={broken:'unknown'};sources=[];liveError='研究已保存，但判断刷新失败，请点击真实数据重试。';busy=false;status('保存成功，判断尚未刷新。',true);}render();}catch{if(seq!==sequence)return;busy=false;status('保存失败，请重试。填写内容仍保留。',true);render();}};
$('apply-risk').onclick=()=>{if(!research)return;values={...values,broken:'yes'};change='本次变化：完整路径候选 → 基本面拦截。新增假设：经营指引重大下修，原研究假设失效。';status('风险情景已应用；原演示研究仍保留，可返回候选情景。');render();$('verdict-title').scrollIntoView({behavior:'smooth',block:'center'});};
$('restore-demo').onclick=()=>{applyResearch(research);change='已移除假设风险，恢复已填写的演示研究。';render();};setDemo();
})();
